CREATE TABLE "RetentionPolicy" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"dataClass" TEXT NOT NULL,"retentionDays" INTEGER NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RetentionPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LegalHold" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"scopeType" TEXT NOT NULL,"scopeId" TEXT,"reason" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"releasedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LegalHold_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LegalHoldEvent" ("id" BIGSERIAL NOT NULL,"legalHoldId" TEXT NOT NULL,"action" TEXT NOT NULL,"actorId" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LegalHoldEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DeletionJob" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"dataClass" TEXT NOT NULL,"cutoff" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'PREVIEWED',"scope" JSONB NOT NULL,"candidateIds" JSONB NOT NULL,"candidateCount" INTEGER NOT NULL,"previewHash" TEXT NOT NULL,"approvedById" TEXT,"approvedAt" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 0,"completedAt" TIMESTAMP(3),"lastError" TEXT,"evidence" JSONB,"evidenceHash" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DeletionJob_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RetentionPolicy_organizationId_dataClass_key" ON "RetentionPolicy"("organizationId","dataClass");
CREATE INDEX "LegalHold_organizationId_releasedAt_startsAt_idx" ON "LegalHold"("organizationId","releasedAt","startsAt");
CREATE INDEX "LegalHoldEvent_legalHoldId_createdAt_idx" ON "LegalHoldEvent"("legalHoldId","createdAt");
CREATE INDEX "DeletionJob_organizationId_status_createdAt_idx" ON "DeletionJob"("organizationId","status","createdAt");
ALTER TABLE "RetentionPolicy" ADD CONSTRAINT "RetentionPolicy_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LegalHold" ADD CONSTRAINT "LegalHold_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LegalHoldEvent" ADD CONSTRAINT "LegalHoldEvent_legalHoldId_fkey" FOREIGN KEY ("legalHoldId") REFERENCES "LegalHold"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DeletionJob" ADD CONSTRAINT "DeletionJob_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
